	GAME1_ENDCREDS1		DB			' screen scroll down                              ', '$'				
						DB			'                                                 ', '$' 	
						DB			' At first I just named it "CAR DODGE" thinking   ', '$' 
						DB			' that I might make a game where a car dodges an  ', '$' 
						DB			' obstacle and have it a finish line and thats it ', '$' 
						DB			'                                                 ', '$' 
						DB			' But the problem is, the idea is very very very  ', '$' 	
						DB			' straightforward with no challenge or anything   ', '$'
						DB			' that could actually give entertainment.         ', '$'
						DB			'                                                 ', '$'
						DB			' So what I did, I added something "COLLECTIBLES" ', '$'
						DB			' and a score text on the buttom screen and       ', '$'
						DB			' deleted the finish line but replaced it with    ', '$'						
						DB			' total score in which it completes when the      ', '$' 
						DB			' specified goal is attained.                     ', '$' 
						DB			'                                                 ', '$' 
						DB			' Basically it is an entirely different game now  ', '$'
						DB			' than what I personally took on. It was not an   ', '$' 
						DB			' easy coding journey I tell you. It has lots of  ', '$' 
						DB			' bugs to be fixed and more testing to be made    ', '$' 
						DB			'                                                 ', '$' 
						DB			' Eventually, I finished it. Played it. Got bored ', '$' 
						DB			' It was really easy, and the collectible did not ', '$' 
						DB			' give any purpose really but adding scores it    ', '$'
						DB			' was still the same boring game.                 ', '$' 
						DB			'                                                 ', '$' 
						DB			' The final decision I made is, adding a feature  ', '$'
						DB			' and more collectibles and a harder obstacles.   ', '$' 
						DB          ' The feature I had thought of is, PHASING STATE  ', '$' 
						DB          '                                                 ', '$' 
						DB			' I wont bother explaining it because you already ', '$' 
						DB			' know what PHASING STATE is. Now, the code is    ', '$' 
						DB			' very mind tiring. Sleep at 4am wake up at 8am   ', '$' 
						DB			' to design and implement this piece of feature   ', '$' 
						DB			'                                                 ', '$'
						DB			' Changed "CAR DODGE" to "PHASE CAR"              ', '$'
						DB			' And now here it is. And you just completed it!  ', '$'
								
