	GAME2_ENDCREDS2		DB			'To put into numbers, around 5 major changes      ', '$'
						DB			'                                                 ', '$'				
						DB			'First ; Well I put in the code and made a simple ', '$' 	
						DB			'        WORD TWIST game.                         ', '$' 
						DB			'                                                 ', '$' 
						DB			'Second; I initially thought the game is too      ', '$' 
						DB			'        straightforward with no special features ', '$' 
						DB			'        so I made it more of a crosswordish game ', '$' 	
						DB			'                                                 ', '$'
						DB			'Third ; Code was finished but as I was playing I ', '$'
						DB			'        realized  that most  words that I picked ', '$'
						DB			'        probably has never been seen and used by ', '$'
						DB			'        whomever person will play this game      ', '$'
						DB			'                                                 ', '$'						
						DB			'Fourth; To  solve the  third problem I put in the', '$' 
						DB			'        definitions  except for  the master words', '$' 
						DB			'        because  I like it  to  remain  difficult', '$' 
						DB			'        and  since the  game is  now a  crossword', '$'
						DB			'        puzzle with WORD TWIST, I renamed it from', '$' 
						DB			'        WORD TWIST  to  CROSS(WORD) TWISTER.  The', '$' 
						DB			'        game  is now  finished and feels like 100', '$' 
						DB			'        times better than I initially coded but I', '$' 
						DB			'        realized something.  It is not word twist', '$' 
						DB			'        if  the  shuffled  words  could  not   be', '$' 
						DB			'        reshuffled.                              ', '$'
						DB			'                                                 ', '$' 
						DB			'Fifth ; Added reshuffling  and decided this would', '$' 
						DB			'        be the final change to  be made as I felt', '$'
						DB			'        satisfied with it.                       ', '$' 
						DB          '                                                 ', '$' 
						DB          '                                                 ', '$' 
						DB			'My girlfriend told me to put health bars and it  ', '$' 
						DB			'decrements every wrong combination you make      ', '$' 
						DB			'                                                 ', '$' 
						DB			'I rejected the idea of adding it because I know  ', '$' 
						DB			'the feeling of playing a word twist game, doing  ', '$'
						DB			'some  guessing  and  being wrong all  the time!  ', '$'
						DB			'Adding healthbars would just piss you off and I  ', '$'
						DB			'know  you might not  continue to  Level 10 if I  ', '$'
						DB			'implemented the idea.                            ', '$'
						DB			'                                                 ', '$' 
						DB			'All the  master words  that are used  for all the', '$'  
						DB			'levels can  be found in  my all-time  most played', '$'  
						DB			'game, DOTA 2. Each words represents a hero.      ', '$'  
						DB			'                                                 ', '$'			
						DB			'Chronosphere = Faceless Void                     ', '$'  
						DB			'Armageddon   = Chaos Knight                      ', '$'  
						DB			'Invocation   = Carl the Invoker                  ', '$'	 
						DB			'Telekinesis  = Rubick,Grand Magus                ', '$'   
						DB			'Metamorphic  = Terrorblade, Demon Marauder       ', '$'   
						DB			'Reincarnate  = Ostarion, Wraith King             ', '$'    
						DB			'Marksmanship = Traxex, Drow Ranger               ', '$'    
						DB			'Imprisonment = Harbringer the Outworld Devourer  ', '$'     
						DB			'Illuminate   = Ezalor, Keeper of the Light       ', '$'    
						DB			'Gyrocopter   = Aurel, the Gyrocopter             ', '$'  
							
