	MAIN PROC NEAR
	
		MOV AL, 03H
		CALL VIDEO_MODE

		CALL FIRSTSCREEN
		
		MASTER_JUMP :
		
		CALL SECONDSCREEN
		
		CMP RAND_STORE, 01H
		IF E JMP GAME1
		
		CMP RAND_STORE, 02H
		IF E JMP GAME2
		
		CMP RAND_STORE, 03H
		IF E CALL EXITPAGE
        JMP EXIT
		
		GAME1 :
		CALL GAME1_LOADINGSCREEN
		CALL GAME1_INSTRUCTION
		CALL GAME1_LEVEL3
		
		GAME2 :
		CALL GAME2_LOADINGSCREEN
		CALL GAME2_INSTRUCTION
		CALL GAME2_LEVEL1
		
		EXIT : INT 20H
	
	MAIN ENDP
	
	CLEAR_ALL PROC NEAR

		MOV AX, 0600H
		MOV BH, 0FH
		MOV CX, 0000H
		MOV DX, 184FH
		INT 10H
		
		RET
	CLEAR_ALL ENDP
	
	CLEAR PROC NEAR

		MOV AX, 0600H
		INT 10H
		
		RET
	CLEAR ENDP
	
	CLEAR_DOWN PROC NEAR

		MOV AX, 0701H
		MOV BH, 0FH
		INT 10H

		RET
	CLEAR_DOWN ENDP
	
	READ_CURSOR PROC NEAR
	
		MOV AH, 08H
		MOV BH, 00H
		INT 10H

		RET	
	READ_CURSOR ENDP
	
	CURSOR PROC NEAR
	
		MOV AH, 02H
		MOV BH, 00H
		INT 10H
		
		RET
	CURSOR ENDP
	
	VIDEO_MODE PROC NEAR
	
		MOV AH, 00H
		INT 10H
		
		RET
	VIDEO_MODE ENDP
	
	DISPLAY PROC NEAR

		MOV AH, 09H
		INT 21H

		RET
	DISPLAY ENDP
	
	CHAR_DISPLAY PROC NEAR
	
		MOV AH, 02H
		INT 21H
		
		RET
	CHAR_DISPLAY ENDP
	
	CHAR_DISPLAY_ATTRIB PROC NEAR
		
		MOV AH, 09H
		MOV BH, 00H
		MOV CX, 01H
		INT 10H
		
		RET
	CHAR_DISPLAY_ATTRIB ENDP
	
	DELAY PROC NEAR
	
		MOV AH, 86H
		MOV AL, 00H
		INT 15H
		
		RET
	DELAY ENDP
	
	FIRSTSCREEN PROC NEAR
	
		MOV BH, 0FH
		MOV CX, 0000H
		MOV DX, 184FH
		CALL CLEAR
		
		; Background First Quadrant

		MOV BH, 6FH
		MOV CX, 0000H
		MOV DX, 0227H
		CALL CLEAR
		
		MOV CX, 0200H
		MOV DX, 041EH
		CALL CLEAR
		
		MOV CX, 0400H
		MOV DX, 0617H
		CALL CLEAR
		
		MOV CX, 0600H
		MOV DX, 0E10H
		CALL CLEAR
		
		; Background Second Quadrant
		
		MOV CX, 0028H
		MOV DX, 024FH
		CALL CLEAR
		
		MOV CX, 0230H
		MOV DX, 044FH
		CALL CLEAR
		
		MOV CX, 0437H
		MOV DX, 064FH
		CALL CLEAR
		
		MOV CX, 063EH
		MOV DX, 0E4FH
		CALL CLEAR
		
		; Background Third Quadrant
		
		MOV CX, 0E00H
		MOV DX, 1810H
		CALL CLEAR
		
		MOV CX, 1710H
		MOV DX, 1827H
		CALL CLEAR
		
		; Background Fourth Quadrant
		
		MOV CX, 0E3EH
		MOV DX, 184FH
		CALL CLEAR
		
		MOV CX, 1728H
		MOV DX, 184FH
		CALL CLEAR
		
		; Head Border First Half
		
		MOV BH, 4FH
		MOV CX, 021EH
		MOV DX, 0226H
		CALL CLEAR
		
		MOV CX, 021DH
		MOV DX, 041EH
		CALL CLEAR
		
		MOV CX, 0417H
		MOV DX, 041EH
		CALL CLEAR
		
		MOV CX, 0417H
		MOV DX, 0618H
		CALL CLEAR
		
		MOV CX, 0610H
		MOV DX, 0618H
		CALL CLEAR
		
		MOV CX, 060FH
		MOV DX, 1510H
		CALL CLEAR
		
		MOV CX, 160FH
		MOV DX, 1625H
		CALL CLEAR
		
		MOV CX, 1021H
		MOV DX, 1525H
		CALL CLEAR
		
		MOV CX, 121AH
		MOV DX, 151EH
		CALL CLEAR
		
		MOV CX, 1413H
		MOV DX, 1517H
		CALL CLEAR
		
		; Head Border Second Half
		
		MOV CX, 0227H
		MOV DX, 0230H
		CALL CLEAR
		
		MOV CX, 0230H
		MOV DX, 0431H
		CALL CLEAR
		
		MOV CX, 0431H
		MOV DX, 0437H
		CALL CLEAR
		
		MOV CX, 0437H
		MOV DX, 0638H
		CALL CLEAR
		
		MOV CX, 0638H
		MOV DX, 063DH
		CALL CLEAR
		
		MOV CX, 063EH
		MOV DX, 153FH
		CALL CLEAR
		
		MOV CX, 1629H
		MOV DX, 163FH
		CALL CLEAR
		
		MOV CX, 1029H
		MOV DX, 162DH
		CALL CLEAR
		
		MOV CX, 1230H
		MOV DX, 1634H
		CALL CLEAR
		
		MOV CX, 1437H
		MOV DX, 163BH
		CALL CLEAR
		
		; Blue Borders
		
		MOV BH, 1FH
		MOV CX, 0000H
		MOV DX, 004FH
		CALL CLEAR
		
		MOV CX, 0000H
		MOV DX, 1801H
		CALL CLEAR
		
		MOV CX, 004EH
		MOV DX, 184FH
		CALL CLEAR
		
		MOV CX, 1800H
		MOV DX, 184FH
		CALL CLEAR
		
		; Prompt Color
		
		MOV BH, 0EH
		MOV CX, 0916H
		MOV DX, 0D39H
		CALL CLEAR
		
		MOV BH, 06H
		MOV CX, 091FH
		MOV DX, 092FH
		CALL CLEAR
		
		MOV BH, 70H
		MOV CX, 0B1FH
		MOV DX, 0B2FH
		CALL CLEAR
		
		MOV BH, 02H
		MOV CX, 0D1BH
		MOV DX, 0D34H
		CALL CLEAR
	 
		; Printing Input Prompt
		MOV DX, 0900H
		CALL CURSOR
		LEA DX, IGNPROMPT
		CALL DISPLAY
		
		; Asking for UserName
		MOV DX, 0B22H
		CALL CURSOR
		
		MOV AH, 0AH
		LEA DX, GAMENAME
		INT 21H
		
		MOV BH, 00H
		MOV BL, GAMENAMELEN
		
		MOV GAMENAMEDATA[BX], '$'
		
		RET
	FIRSTSCREEN ENDP
	
	SECONDSCREEN PROC NEAR
	
		CALL CLEAR_ALL
		
		; Coloring 'G'
		MOV BH, 09H
		MOV CX, 0100H
		MOV DX, 0509H
		CALL CLEAR
		
		; Coloring 'A'
		MOV BH, 0AH
		MOV CX, 010BH
		MOV DX, 0512H
		CALL CLEAR
		
		; Coloring 'M'
		MOV BH, 0BH
		MOV CX, 0115H
		MOV DX, 051DH
		CALL CLEAR
		
		; Coloring 'E'
		MOV BH, 0CH
		MOV CX, 0120H
		MOV DX, 0526H
		CALL CLEAR
		
		; Coloring 'M'
		MOV BH, 03H
		MOV CX, 012BH
		MOV DX, 0533H
		CALL CLEAR
		
		; Coloring 'E'
		MOV BH, 04H
		MOV CX, 0136H
		MOV DX, 053BH
		CALL CLEAR
		
		; Coloring 'N'
		MOV BH, 05H
		MOV CX, 013EH
		MOV DX, 0545H
		CALL CLEAR
		
		; Coloring 'U'
		MOV BH, 01H
		MOV CX, 0148H
		MOV DX, 054EH
		CALL CLEAR
		
		; Printing 'GAME MENU'
		MOV DX, 0100H
		CALL CURSOR
		LEA DX, GAMEMENU
		CALL DISPLAY
		
		; Coloring 'MENU TABLE' Borders
		MOV BH, 0EH
		MOV CX, 0713H
		MOV DX, 113CH
		CALL CLEAR
		
		; Coloring INENTERPROMPT
		MOV BH, 06H
		MOV CX, 0A1BH
		MOV DX, 0A35H
		CALL CLEAR
		
		; Coloring WSX Prompt
		MOV BH, 0FH
		MOV CX, 0C1BH
		MOV DX, 0E33H
		CALL CLEAR
		
		; Printing 'MENU TABLE'
		MOV DX, 0700H
		CALL CURSOR
		LEA DX, MENUTABLE
		CALL DISPLAY
		
		; Printing 'MENU TABLE Contents'
		MOV DX, 0A1AH
		CALL CURSOR
		LEA DX, INENTERPROMPT
		CALL DISPLAY
		
		MOV DX, 0C1BH
		CALL CURSOR
		LEA DX, INWPROMPT
		CALL DISPLAY
		
		MOV DX, 0D1BH
		CALL CURSOR
		LEA DX, INSPROMPT
		CALL DISPLAY
		
		MOV DX, 0E1BH
		CALL CURSOR
		LEA DX, INXPROMPT
		CALL DISPLAY
		
		MOV DX, 184FH
		CALL CURSOR
		
		ARROW_AGAIN :
		
			MOV AH, 07H
			INT 21H
			
			CMP AL, 'w'
			IF E CALL SECONDSCREEN_CARSHOW
			
			CMP AL, 's'
			IF E CALL SECONDSCREEN_WORDSHOW
			
			CMP AL, 'x'
			IF E CALL SECONDSCREEN_EXIT
			
			CMP AL, 0DH
			IF E RET
			
			
			MOV AH, 0CH
			MOV AL, 00H
			INT 21H
			
		JMP ARROW_AGAIN
		
		RET
	SECONDSCREEN ENDP
	
	SECONDSCREEN_CARSHOW PROC NEAR
	
		MOV RAND_STORE[0], 01H
		
		; Coloring W Prompt
		MOV BH, 70H
		MOV CX, 0C15H
		MOV DX, 0C3AH
		CALL CLEAR
		
		; Unhighlighting S Prompt
		MOV BH, 0FH
		MOV CX, 0D15H
		MOV DX, 0D3AH
		CALL CLEAR
		
		; Unhighlighting X Prompt
		MOV BH, 0FH
		MOV CX, 0E15H
		MOV DX, 0E3AH
		CALL CLEAR
		
		; Printing 'MENU TABLE Contents'
		MOV DX, 0A1AH
		CALL CURSOR
		LEA DX, INENTERPROMPT
		CALL DISPLAY
		
		MOV DX, 0C1BH
		CALL CURSOR
		LEA DX, INWPROMPT
		CALL DISPLAY
		
		MOV DX, 0D1BH
		CALL CURSOR
		LEA DX, INSPROMPT
		CALL DISPLAY
		
		MOV DX, 0E1BH
		CALL CURSOR
		LEA DX, INXPROMPT
		CALL DISPLAY

		PUSHA
		MOV BH, 04H
		MOV CX, 1200H
		MOV DX, 164FH
		CALL CLEAR
		POPA
		
		MOV CX, 50H
		MOV DL, 25H
		
		CARSHOWLOOP :
		
			MOV DH, 12H
			
			; Car Printing
			INC DH
			CALL CURSOR
			PUSH DX
			LEA DX, CAR1
			CALL DISPLAY
			POP DX
			
			INC DH
			CALL CURSOR
			PUSH DX
			LEA DX, CAR2
			CALL DISPLAY
			POP DX

			INC DH
			CALL CURSOR
			PUSH DX
			LEA DX, CAR3
			CALL DISPLAY
			POP DX
			
			INC DH
			CALL CURSOR
			PUSH DX
			LEA DX, CAR4
			CALL DISPLAY
			POP DX
			
			INC DH
			CALL CURSOR
			PUSH DX
			LEA DX, CAR5
			CALL DISPLAY
			POP DX

			PUSHA
			MOV BH, 00H
			MOV CX, 1700H
			MOV DX, 184FH
			CALL CLEAR
			POPA
			
			CMP CX, 20H
			IF NE JMP CARSHOW_NE
			
			PUSHA
			MOV BH, 00H
			MOV CX, 153DH
			MOV DX, 184FH
			CALL CLEAR
			POPA
			
			CARSHOW_NE :
			
			DEC DL
			
			PUSHA
			MOV CX, 00H
			MOV DX, 12000
			CALL DELAY
			POPA
			
		LOOP CARSHOWLOOP
		
		
		RET
	SECONDSCREEN_CARSHOW ENDP

	SECONDSCREEN_WORDSHOW PROC NEAR
	
		MOV RAND_STORE[0], 02H
		
		; Highlighting S Prompt
		MOV BH, 70H
		MOV CX, 0D15H
		MOV DX, 0D3AH
		CALL CLEAR
		
		; Unhighlighting W Prompt
		MOV BH, 0FH
		MOV CX, 0C15H
		MOV DX, 0C3AH
		CALL CLEAR
		
		; Unhighlighting X Prompt
		MOV BH, 0FH
		MOV CX, 0E15H
		MOV DX, 0E3AH
		CALL CLEAR
		
		; Printing 'MENU TABLE Contents'
		MOV DX, 0A1AH
		CALL CURSOR
		LEA DX, INENTERPROMPT
		CALL DISPLAY
		
		MOV DX, 0C1BH
		CALL CURSOR
		LEA DX, INWPROMPT
		CALL DISPLAY
		
		MOV DX, 0D1BH
		CALL CURSOR
		LEA DX, INSPROMPT
		CALL DISPLAY
		
		MOV DX, 0E1BH
		CALL CURSOR
		LEA DX, INXPROMPT
		CALL DISPLAY
	
		MOV BH, 0FH
		MOV CX, 1200H
		MOV DX, 184FH
		CALL CLEAR
		
		MOV CX, 0005H
		MOV BX, 0
		
		WORDSHOWLOOP :
		
			PUSHA
			MOV DX, 1300H
			CALL CURSOR
			POPA
			
			MOV LOOPSTORE[0], CL
			
			PUSHA
			ADD LOOPSTORE[0], 09H
			MOV BH, LOOPSTORE[0]
			MOV CX, 1300H
			MOV DX, 164FH
			CALL CLEAR
			POPA
			
			PUSH DX
			LEA DX, WORDTWIST[BX]
			PUSH BX
			CALL DISPLAY
			POP BX
			POP DX
			
			PUSHA
			MOV CX, 03H
			MOV DX, 00H
			CALL DELAY
			POPA
			
			ADD BX, 141H
			DEC CX
			
			CMP CX, 00
			IF E JMP WORDSHOW_DONE
			
		JMP WORDSHOWLOOP
		
		WORDSHOW_DONE :
		
		MOV DX, 1300H
		CALL CURSOR	
		LEA DX, WORDTWIST[00]
		CALL DISPLAY
		
		RET
		
	SECONDSCREEN_WORDSHOW ENDP
	
	SECONDSCREEN_EXIT PROC NEAR
	
		MOV RAND_STORE[0], 03H
			
		; Highlighting X Prompt
		MOV BH, 70H
		MOV CX, 0E15H
		MOV DX, 0E3AH
		CALL CLEAR
		
		; Unhighlighting W Prompt
		MOV BH, 0FH
		MOV CX, 0C15H
		MOV DX, 0C3AH
		CALL CLEAR
		
		; Unhighlighting S Prompt
		MOV BH, 0FH
		MOV CX, 0D15H
		MOV DX, 0D3AH
		CALL CLEAR
		
		; Printing 'MENU TABLE Contents'
		MOV DX, 0A1AH
		CALL CURSOR
		LEA DX, INENTERPROMPT
		CALL DISPLAY
		
		MOV DX, 0C1BH
		CALL CURSOR
		LEA DX, INWPROMPT
		CALL DISPLAY
		
		MOV DX, 0D1BH
		CALL CURSOR
		LEA DX, INSPROMPT
		CALL DISPLAY
		
		MOV DX, 0E1BH
		CALL CURSOR
		LEA DX, INXPROMPT
		CALL DISPLAY
		
		MOV BH, 0FH
		MOV CX, 1300H
		MOV DX, 184FH
		CALL CLEAR
		
		MOV DX, 1312H
		CALL CURSOR
		LEA DX, GAMENAMEDATA
		CALL DISPLAY
		LEA DX, EXITNOTICE1
		CALL DISPLAY
		
		MOV DX, 1600H
		CALL CURSOR
		LEA DX, EXITNOTICE2
		CALL DISPLAY
		
		
		MOV DX, 184FH
		CALL CURSOR
	
		RET
	SECONDSCREEN_EXIT ENDP
	
	GAME1_LOADINGSCREEN PROC NEAR
	
		CALL CLEAR_ALL
		
		; Coloring BORDER
		MOV BH, 0EH
		MOV CX, 0100H
		MOV DX, 064FH
		CALL CLEAR
		
		; Coloring CAR
		MOV BH, 04H
		MOV CX, 0700H
		MOV DX, 104FH
		CALL CLEAR
		
		; Blinking 'P'
		MOV BH, 81H
		MOV CX, 0203H
		MOV DX, 0508H
		CALL CLEAR

		; Blinking 'H'
		MOV BH, 82H
		MOV CX, 020CH
		MOV DX, 0511H
		CALL CLEAR
		
		; Blinking 'A'
		MOV BH, 83H
		MOV CX, 0215H
		MOV DX, 051AH
		CALL CLEAR
		
		; Blinking 'S'
		MOV BH, 84H
		MOV CX, 021EH
		MOV DX, 0523H
		CALL CLEAR
		
		; Blinking 'E'
		MOV BH, 85H
		MOV CX, 0227H
		MOV DX, 052CH
		CALL CLEAR
		
		; Coloring 'C'
		MOV BH, 06H
		MOV CX, 0232H
		MOV DX, 0539H
		CALL CLEAR
		
		; Coloring 'A'
		MOV BH, 06H
		MOV CX, 023CH
		MOV DX, 0542H
		CALL CLEAR
		
		; Coloring 'R'
		MOV BH, 06H
		MOV CX, 0247H
		MOV DX, 054CH
		CALL CLEAR
		
		MOV DX, 0100H
		CALL CURSOR
		LEA DX, LOADING_PHASECAR
		CALL DISPLAY
		
		MOV DX, 0800H
		CALL CURSOR
		LEA DX, CAR_LOADING
		CALL DISPLAY
		
		; Hides Cursor
		MOV BH, 00H
		MOV CX, 154AH
		MOV DX, 184FH
		CALL CLEAR
		
		MOV CX, 2CH
		MOV BX, 00H
		
		MOV LOOPSTORE[0], 12H

		LOADREPEAT1 :
		
		    ; Displays Loading Prompt 
			MOV DX, 1300H
			CALL CURSOR
			LEA DX, LOADING[BX]
			CALL DISPLAY			
			
			MOV DX, 1400H
			CALL CURSOR
			LEA DX, LOADING_BORDER
			CALL DISPLAY

			PUSHA
			MOV BH, 70H
			MOV CX, 1512H
			MOV DH, 15H
			MOV DL, LOOPSTORE[0]
			CALL CLEAR
			POPA
			
			INC LOOPSTORE[0]
			ADD BX, 51H
			
			
			CMP BX, 243
			IF E MOV BX, 00H
			
			PUSHA
			MOV CX, 03H
			MOV DX, 00H
			
			MOV AH, 86H
			MOV AL, 00H
			INT 15H
		
			POPA
			
			DEC CX
			
			CMP CX, 00H
			IF E JMP LOAD1_DONE 
	
	    JMP LOADREPEAT1
		
		LOAD1_DONE :

		RET
	GAME1_LOADINGSCREEN ENDP
		
	GAME1_INSTRUCTION PROC NEAR
	
		CALL CLEAR_ALL
		
		MOV AL, 00
		CALL VIDEO_MODE
		
		MOV AH, 0CH
		INT 21h 

		; Coloring BORDER
		MOV BH, 06H
		MOV CX, 0101H
		MOV DX, 174EH
		CALL CLEAR
		
		; Coloring GAME_INFO
		MOV BH, 0EH
		MOV CX, 0200H
		MOV DX, 021BH
		CALL CLEAR
		
		; Coloring INDENT_TEXT
		MOV BH, 0FH
		MOV CX, 0402H
		MOV DX, 1625H
		CALL CLEAR
		
		; Coloring MECHANICS/RULES
		MOV BH, 04H
		MOV CX, 0B02H
		MOV DX, 0B25H
		CALL CLEAR
		
		; Coloring OBSTACLE
		MOV BH, 08H
		MOV CX, 0910H
		MOV DX, 0925H
		CALL CLEAR

		; Coloring COLLECTIBLE
		MOV BH, 05H
		MOV CX, 0810H
		MOV DX, 0825
		CALL CLEAR
		
		; Coloring INDENT_TITLE
		MOV BH, 01H
		MOV CX, 0405H
		MOV DX, 080DH
		CALL CLEAR
		
		; Coloring ARROWS
		MOV BH, 02H
		MOV CX, 0403H
		MOV DX, 0803H
		CALL CLEAR
		
		; Coloring CONTINUE
		MOV BH, 08H
		MOV CX, 1603H
		MOV DX, 1625H
		CALL CLEAR
		
		; Hide CURSOR
		MOV BH, 00H
		MOV CX, 1600H
		MOV DX, 1800H
		CALL CLEAR
		
		MOV DX, 0200H
		CALL CURSOR
		
		LEA DX, G1_INFO
		CALL DISPLAY
		
		MOV AH, 07H
		INT 21H
		
		RET
	GAME1_INSTRUCTION ENDP
	
	CAR_PRINTER PROC NEAR
	
		PUSHA
				
		MOV DH, POSITION_Y[0]
		MOV DL, POSITION_X[0]
		MOV BX, 00H
		MOV CX, 04H
		
		PRINT_CARHERO :
			
			PUSH BX
			CALL CURSOR
			POP BX
				
			PUSH DX
			LEA DX, CARHERO[BX]
			CALL DISPLAY
			POP DX
			
			ADD BX, 06H
			INC DH
		
		LOOP PRINT_CARHERO 
		
		POPA	
				
		RET
	CAR_PRINTER ENDP
	
	CLEARING_CAR PROC NEAR
		
		PUSHA
	
		CMP CLEAR_STATUS[0], 00H
		IF E MOV BH, 04H
		CMP CLEAR_STATUS[0], 01H
		IF E MOV BH, 00H
		CMP CLEAR_STATUS[0], 02H
		IF E MOV BH, Z_STATUS[0]
		
		MOV CH, POSITION_Y[0]
		MOV CL, POSITION_X[0]
		MOV DH, CH
		MOV DL, CL
		ADD DH, 03H
		ADD DL, 04H
		CALL CLEAR
		
		POPA 
			
		RET	
	CLEARING_CAR ENDP
	
	CURSOR_COLLISION PROC NEAR
	
		PUSHA
		
		MOV DL, POSITION_X[0]
		MOV CX, 02H
		
		COLLIDE_X :
		
			PUSHA
			MOV DH, POSITION_Y[0]
			MOV CX, 04H
			COLLIDE_Y :
			
				CALL CURSOR
				
				PUSHA
				CALL READ_CURSOR
				
				CMP AL, 192
				IF E MOV RETURNER[0], 01H
				CMP AL, 217
				IF E MOV RETURNER[0], 01H
				CMP AL, 218
				IF E MOV RETURNER[0], 01H
				CMP AL, 191
				IF E MOV RETURNER[0], 01H
				CMP AL, 179
				IF E MOV RETURNER[0], 01H
				CMP AL, 196
				IF E MOV RETURNER[0], 01H
				CMP AL, 219
				IF E MOV RETURNER[0], 01H
				CMP AL, 234
				IF E INC SCORESTORE[0]
				CMP AL, 233
				IF E ADD SCORESTORE[0], 02H
				CMP AL, 235
				IF E ADD SCORESTORE[0], 05H
				CMP AL, 235
				IF E ADD Z_TIME[0], 20

				POPA
				
				ADD DH, 01H
				
			LOOP COLLIDE_Y
			POPA
			
			ADD DL, 04H
			
		LOOP COLLIDE_X
		
		PUSHA
		
		MOV DH, POSITION_Y[0]
		MOV DL, POSITION_X[0]
		MOV CX, 03H
		
		COLLIDE_TOP :
		
			INC DL
			CALL CURSOR
			
			PUSHA
			CALL READ_CURSOR
			CMP AL, 192
			IF E MOV RETURNER[0], 01H
			CMP AL, 217
			IF E MOV RETURNER[0], 01H
			CMP AL, 218
			IF E MOV RETURNER[0], 01H
			CMP AL, 191
			IF E MOV RETURNER[0], 01H
			CMP AL, 179
			IF E MOV RETURNER[0], 01H
			CMP AL, 196
			IF E MOV RETURNER[0], 01H
			CMP AL, 219
			IF E MOV RETURNER[0], 01H
			CMP AL, 234
			IF E INC SCORESTORE[0]
			CMP AL, 233
			IF E ADD SCORESTORE[0], 02H
			CMP AL, 235
			IF E ADD SCORESTORE[0], 05H
			CMP AL, 235
			IF E ADD Z_TIME[0], 20
			CMP AL, 236
			IF E ADD SCORESTORE[0], 50
			POPA

		LOOP COLLIDE_TOP
		
		POPA
		POPA
		
		RET
	CURSOR_COLLISION ENDP
		
	PRINT_CONVERTED_ZTIME PROC NEAR
	
		MOV DX, 1849H
		CALL CURSOR
		MOV DL, DIGIT1[0] 
		CALL CHAR_DISPLAY

		MOV DX, 184AH
		CALL CURSOR
		MOV DL, DIGIT2[0] 
		CALL CHAR_DISPLAY
	
		MOV DX, 184BH
		CALL CURSOR
		MOV DL, DIGIT3[0] 
		CALL CHAR_DISPLAY

		RET
	PRINT_CONVERTED_ZTIME ENDP
	
	PRINT_CONVERTED_SCORE PROC NEAR
	
		MOV DX, 182EH
		CALL CURSOR
		MOV DL, DIGIT2[0] 
		CALL CHAR_DISPLAY

		MOV DX, 182FH
		CALL CURSOR
		MOV DL, DIGIT3[0] 
		CALL CHAR_DISPLAY

		RET
	PRINT_CONVERTED_SCORE ENDP
	
	INT_CONVERTOR PROC NEAR
	
		;COMPARE 1
		CMP AX, 100
		JB STORE_A0
		JE STORE_A1
		JA	D_A1
		
		JMP DIGIT1_SUB
		
			STORE_A0 : 
		
				MOV DIGIT1[0], '0'
				JMP DIGIT1_SUB
				
			STORE_A1 : 
		
				MOV DIGIT1[0], '1'
				JMP DIGIT1_SUB
	
		D_A1: 
		
			CMP AX, 200
			JB STORE_A1

			STORE_A2 : MOV DIGIT1[0], '2'
	
		DIGIT1_SUB :
		
			CMP DIGIT1[0], '1'
			IF E SUB AX, 100
			CMP DIGIT1[0], '2'
			IF E SUB AX, 200
		
		;COMPARE2
	
		CMP AX, 09
		JB STORE_B0
		JE STORE_B0
		JA D_B1
		
		D_B1 :	
			
			CMP AX, 19
			JB STORE_B1
			JE STORE_B1
			JA D_B2

		D_B2:	
		
			CMP AX, 29
			JB STORE_B2
			JE STORE_B2
			JA D_B3
		
		D_B3:	
		
			CMP AX, 39
			JB STORE_B3
			JE STORE_B3
			JA D_B4
		
		D_B4:
		
			CMP AX, 49
			JB STORE_B4
			JE STORE_B4
			JA D_B5
		
		D_B5:
	
			CMP AX, 59
			JB STORE_B5
			JE STORE_B5
			JA D_B6
		
		D_B6:	
	
			CMP AX, 69
			JB STORE_B6
			JE STORE_B6
			JA D_B7
		
		D_B7:
	
			CMP AX, 79
			JB STORE_B7
			JE STORE_B7
			JA D_B8
		
		D_B8 :
		
			CMP AX, 89
			JB STORE_B8
			JE STORE_B8
			JA D_B9
		
		D_B9 :	
		
			CMP AX, 99
			JB STORE_B9
			JE STORE_B9
	
			STORE_B0 : 
			
				MOV DIGIT2[0], '0'
				JMP DIGIT2_SUB
				
			STORE_B1 : 
			
				MOV DIGIT2[0], '1'
				JMP DIGIT2_SUB
				
			STORE_B2 : 
			
				MOV DIGIT2[0], '2'
				JMP DIGIT2_SUB
				
			STORE_B3 : 
			
				MOV DIGIT2[0], '3'
				JMP DIGIT2_SUB
				
			STORE_B4 : 
			
				MOV DIGIT2[0], '4'
				JMP DIGIT2_SUB
			   
			STORE_B5 : 
			
				MOV DIGIT2[0], '5'
				JMP DIGIT2_SUB
			   
			STORE_B6 : 
			
				MOV DIGIT2[0], '6'
				JMP DIGIT2_SUB
			   
			STORE_B7 : 
			
				MOV DIGIT2[0], '7'
				JMP DIGIT2_SUB
					
			STORE_B8 : 
			
				MOV DIGIT2[0], '8'
				JMP DIGIT2_SUB
					
			STORE_B9 : 
			
				MOV DIGIT2[0], '9'
	
		DIGIT2_SUB :
		
			CMP DIGIT2[0], '1'
			IF E SUB AX, 10
			CMP DIGIT2[0], '2'
			IF E SUB AX, 20
			CMP DIGIT2[0], '3'
			IF E SUB AX, 30
			CMP DIGIT2[0], '4'
			IF E SUB AX, 40
			CMP DIGIT2[0], '5'
			IF E SUB AX, 50
			CMP DIGIT2[0], '6'
			IF E SUB AX, 60
			CMP DIGIT2[0], '7'
			IF E SUB AX, 70
			CMP DIGIT2[0], '8'
			IF E SUB AX, 80
			CMP DIGIT2[0], '9'
			IF E SUB AX, 90
		
		;COMPARE 3
	
		CMP AX, 00
		IF E MOV DIGIT3[0], '0'
		CMP AX, 01
		IF E MOV DIGIT3[0], '1'
		CMP AX, 02
		IF E MOV DIGIT3[0], '2'
		CMP AX, 03
		IF E MOV DIGIT3[0], '3'
		CMP AX, 04
		IF E MOV DIGIT3[0], '4'
		CMP AX, 05
		IF E MOV DIGIT3[0], '5'
		CMP AX, 06
		IF E MOV DIGIT3[0], '6'
		CMP AX, 07
		IF E MOV DIGIT3[0], '7'
		CMP AX, 08
		IF E MOV DIGIT3[0], '8'
		CMP AX, 09
		IF E MOV DIGIT3[0], '9'
	
		RET
	INT_CONVERTOR ENDP
	
	GAME1_CONGRATS PROC NEAR
	
		PUSHA
	
		; Coloring CONGRATS
		MOV BH, 64H
		MOV CX, 030BH
		MOV DX, 0644H
		CALL CLEAR
		
		; Coloring ENTER
		MOV BH, 02H
		MOV CX, 070BH
		MOV DX, 0743H
		CALL CLEAR
	
		MOV DX, 0300H
		CALL CURSOR
		LEA DX, G1_CONGRATS
		CALL DISPLAY
		
		G1_NEXTLEVEL :
		
			MOV AH, 07H
			INT 21H
			
			CMP AL, 0DH
			IF E JMP G1_NEXTSTATE

		JMP G1_NEXTLEVEL 
		
		G1_NEXTSTATE :
		
		POPA
		
		RET
	GAME1_CONGRATS ENDP
	
	GAME1_LEVEL3 PROC NEAR
	
		G1L3RETURN :
		
		CALL GAME1_LEVEL3_SHOW

		MOV RETURNER[0], 00H
		MOV SCORESTORE[0], 00H
		MOV Z_TIME[0], 120
		MOV POSITION_X[0], 27H
		MOV POSITION_Y[0], 14H
		
		MOV AL, 03H
		CALL VIDEO_MODE
		
		CALL CLEAR_ALL
		
		MOV DX, 0000H
		CALL CURSOR
		LEA DX, G1_LEVEL3
		CALL DISPLAY
		
		CALL CLEARING_CAR
		CALL CAR_PRINTER
		
		MOV BH, 0EH
		MOV CX, 1800H
		MOV DX, 184FH
		CALL CLEAR
		
		MOV DX, 1800H
		CALL CURSOR
				
		PUSH DX
		LEA DX, GAMEPROMPT_MENU
		CALL DISPLAY
		POP DX
		
		INC DL, 30H
		CALL CURSOR
		LEA DX, GAMEPROMPT_PHASE3
		CALL DISPLAY
				
		MOV AH, 07H
		INT 21H
		
		MOV CHAR_POSITION[0], 7920
		MOV CX, 5000
		
		MOVE_REP3 :
		
			PUSH CX
		
			MOV AH, 01H
			INT 16H
			
			MOV CLEAR_STATUS[0], 01H
			CALL CLEARING_CAR
			
			CMP AL, 'a'
			IF E JMP MOVE_LEFT3
			CMP AL, 'd'
			IF E JMP MOVE_RIGHT3
			CMP AL, 'z'
			IF E JMP Z_ON3
			CMP AL, 'c'
			IF E JMP Z_OFF3
	
			JMP BLINK3 
			
			MOVE_LEFT3 :
			
				DEC POSITION_X[0]
				JMP BLINK3
			
			MOVE_RIGHT3 :
			
				INC POSITION_X[0]
				JMP BLINK3
			
			Z_ON3 : 
			
				MOV Z_STATUS[0], 84H
				JMP BLINK3
			
			Z_OFF3 :
			
				MOV Z_STATUS[0], 04H
			
			BLINK3 :
			
				PUSHA
				MOV CX, 0000H
				MOV DX, 174FH
				CALL CLEAR_DOWN
				POPA
				
				
				CMP Z_TIME[0], 00H
				IF E MOV Z_STATUS[0], 04H
				
				CMP Z_STATUS[0], 04H
				IF NE DEC Z_TIME[0]
				IF E CALL CURSOR_COLLISION
				
				CMP RETURNER[0], 01
				IF E JMP G1L3RETURN
				
				CALL G1L3_ROAD
				
				MOV CLEAR_STATUS[0], 02H
				CALL CLEARING_CAR
				
				MOV AH, 0CH
				MOV AL, 00H
				INT 21H
				
				MOV AH, 00H
				MOV AL, Z_TIME[0]
				CALL INT_CONVERTOR
				CALL PRINT_CONVERTED_ZTIME
				
				MOV AH, 00H
				MOV AL, SCORESTORE[0]
				CALL INT_CONVERTOR
				CALL PRINT_CONVERTED_SCORE
				
			CALL CAR_PRINTER
		
			MOV CX, 01H
			MOV DX, 1000000000
			CALL DELAY

			POP CX
			
			CMP SCORESTORE[0], 50
			JB GAME1_NOTDONE_L3 
			CALL GAME1_CONGRATS
			CALL GAME1_CONGRATS_END

		GAME1_NOTDONE_L3 :
		DEC CX
		CMP CX, 00H
		IF NE JMP MOVE_REP3
		
		RET
	GAME1_LEVEL3 ENDP
	
	GAME1_LEVEL3_SHOW PROC NEAR
	
		CALL CLEAR_ALL
		
		MOV AL, 00H
		CALL VIDEO_MODE
		
		; Coloring BORDER
		MOV BH, 06H
		MOV CX, 0000H
		MOV DX, 1827H
		CALL CLEAR
		
		; Coloring TEXT
		MOV BH, 07H
		MOV CX, 0402H
		MOV DX, 1525H
		CALL CLEAR
		
		; Coloring TITLES
		
		MOV BH, 52H
		MOV CX, 0302H
		MOV DX, 0325H
		CALL CLEAR
		
		MOV CX, 0C02H
		MOV DX, 0C25H
		CALL CLEAR
		
		MOV CX, 0F02H
		MOV DX, 0F25H
		CALL CLEAR
		
		MOV CX, 1302H
		MOV DX, 1325H
		CALL CLEAR
		
		; Coloring LEVEL
		MOV BH, 03H
		MOV CX, 0100H
		MOV DX, 0127H
		CALL CLEAR
		
		MOV DX, 0100H
		CALL Cursor
		LEA DX, G1L3_S
		CALL DISPLAY
		
		; Hide Cursor
		MOV BH, 00H
		MOV CX, 1700H
		MOV DX, 1801H
		CALL CLEAR
		
		MOV CX, 30H
		G1L3SHOW : 
		
			PUSH CX
			MOV AH, 86H
			MOV AL, 00H
			MOV CX, 01H
			MOV DX, 01H
			INT 15H
			POP CX
		
		LOOP G1L3SHOW
		
		RET
	GAME1_LEVEL3_SHOW ENDP

	G1L3_ROAD PROC NEAR

		MOV DX, 0000H
		CALL CURSOR
		
		MOV BX, CHAR_POSITION[0]
		
		LEA DX, G1_LEVEL3_BY1[BX]
		CALL DISPLAY
		
		CMP CHAR_POSITION[0], 00
		IF E MOV CHAR_POSITION[0], 7920
	
		SUB CHAR_POSITION[0], 80
		
		RET
	G1L3_ROAD ENDP
	
	GAME1_CONGRATS_END PROC NEAR  

		CALL CLEAR_ALL
		
		; Coloring CONGRATS
		MOV BH, 46H
		MOV CX, 0200H
		MOV DX, 054FH
		CALL CLEAR
		
		MOV BH, 03H
		MOV CX, 0600H
		MOV DX, 064FH
		CALL CLEAR
		
		MOV BH, 0BH
		MOV CX, 0700H
		MOV DX, 074FH
		CALL CLEAR
		
		
		MOV DX, 0200H
		CALL CURSOR
		LEA DX, G1_CONGRATS
		CALL DISPLAY
		
		MOV DX, 0600H
		CALL CURSOR
		LEA DX, QUANTUMSPECTRE
		CALL DISPLAY
	                         

		; Coloring Border
		MOV BH, 05H
		MOV CX, 0C01H
		MOV DX, 1835H
		CALL CLEAR
		
		; Coloring GAME MAKING
		MOV BH, 06H
		MOV CX, 0B0AH
		MOV DX, 0B2AH
		CALL CLEAR
		
		; Coloring MENU TABLE Border
		MOV BH, 03H
		MOV CX, 0C3AH
		MOV DX, 124AH
		CALL CLEAR
		
		; Coloring MENU TABLE Menu 
		MOV BH, 02H
		MOV CX, 0D3BH
		MOV DX, 0D49H
		CALL CLEAR
		
		; Coloring MENU TABLE Level
		MOV BH, 06H
		MOV CX, 0E3BH
		MOV DX, 1049H
		CALL CLEAR
		
		; Coloring MENU TABLE Exit
		MOV BH, 04H
		MOV CX, 113BH
		MOV DX, 1149H
		CALL CLEAR
		
		MOV BH, 0EH
		MOV CX, 0D03H
		MOV DX, 1733H
		CALL CLEAR
		        
		; Coloring TEXT inside CREDITS
		MOV DX, 0A01H
		CALL CURSOR
		LEA DX, GAME1_ENDCRED_BORD
		CALL DISPLAY
		
		MOV DH, 0BH
		MOV DL, 3AH
		MOV CX, 07H
		MOV BX, 00H
		
		REPRINT_TABLE1 :
			
			CALL CURSOR
		
			PUSH DX
			LEA DX, CRED1_TABLE[BX]
			CALL DISPLAY
			POP DX
			
			ADD BX, 12H
			INC DH
		
		LOOP REPRINT_TABLE1
		
		; Coloring MY NAME
		MOV BH, 09H
		MOV CX, 163CH
		MOV DX, 164FH
		CALL CLEAR
		
		MOV DX, 143CH
		CALL CURSOR
		LEA DX, OWNER1
		CALL DISPLAY
		
		MOV DX, 163CH
		CALL CURSOR
		LEA DX, OWNER2
		CALL DISPLAY
		
		MOV DX, 1800H
		CALL CURSOR
		LEA DX, SCROLLPROMPT
		CALL DISPLAY
		
		MOV CX, 25H
		MOV BX, 00H
		
		UP_CREDS1_AGAIN :
		
			CRED1_ASK :
			MOV AH, 07H
			INT 21H
			
			CMP AL, 'm'
			IF E JMP MASTER_JUMP
			CMP AL, '1'
			IF E CALL GAME1_LEVEL3
			CMP AL, 'x'
			IF E CALL EXITPAGE
			CMP AL, 'w'
			IF NE JMP CRED1_ASK
	
			PUSHA
			MOV AX, 0601H       
			MOV BH, 0EH
			MOV CX, 0C03H
			MOV DX, 1633H
			INT 10H
		
			MOV DX, 1603H
			CALL CURSOR
			POPA
			
			LEA DX, GAME1_ENDCREDS1[BX]
			CALL DISPLAY
			
			ADD BX, 32H
			DEC CX
			
			MOV AH, 0CH
			INT 21H
			
		CMP CX, 00H
		IF NE JMP UP_CREDS1_AGAIN
		
		CRED1_REASK :
			MOV AH, 07H
			INT 21H
			
			CMP AL, 'm'
			IF E JMP MASTER_JUMP
			CMP AL, '1'
			IF E CALL GAME1_LEVEL3
			CMP AL, 'x'
			IF NE JMP CRED1_REASK
			CALL EXITPAGE
	
		RET
	GAME1_CONGRATS_END ENDP
	

	
	GAME2_LOADINGSCREEN PROC NEAR
	
		CALL CLEAR_ALL
		
		; Hides Cursor
		MOV BH, 00H
		MOV CX, 0000H
		MOV DX, 1805H
		CALL CLEAR
		
		MOV CX, 2CH
		MOV BX, 00H
		
		MOV LOOPSTORE[0], 12H
		MOV COLORSTORE[0], 01H
		
		LOADREPEAT2 :
		
			PUSHA
			; Coloring Borders
			MOV BH, 06H
			MOV CX, 030CH
			MOV DX, 0F43H
			CALL CLEAR
		
			; Coloring W in WORD
			MOV BH, COLORSTORE[0]
			MOV CX, 0413H
			MOV DX, 071DH
			CALL CLEAR
		
			; Coloring O in WORD
			MOV BH, COLORSTORE[0] 
			ADD BH, 01H
			MOV CX, 0420H
			MOV DX, 0726H
			CALL CLEAR
		
			; Coloring R in WORD
			MOV BH, COLORSTORE[0]
			ADD BH, 02H
			MOV CX, 042AH
			MOV DX, 0731H
			CALL CLEAR
		
			; Coloring D in WORD
			MOV BH, COLORSTORE[0] 
			ADD BH, 03H
			MOV CX, 0434H
			MOV DX, 073BH
			CALL CLEAR
		
			; Coloring T in TWIST
			MOV BH, COLORSTORE[0]
			ADD BH, 04H
			MOV CX, 0B0DH
			MOV DX, 0E15H
			CALL CLEAR
		
			; Coloring W in TWIST
			MOV BH, COLORSTORE[0]
			ADD BH, 05H
			MOV CX, 0B19H
			MOV DX, 0E21H
			CALL CLEAR
		
			; Coloring I in TWIST
			MOV BH, COLORSTORE[0]
			ADD BH, 06H
			MOV CX, 0B26H
			MOV DX, 0E2CH
			CALL CLEAR
		
			; Coloring S in TWIST
			MOV BH, COLORSTORE[0]
			ADD BH, 07H
			MOV CX, 0B30H
			MOV DX, 0E36H
			CALL CLEAR
		
			; Coloring T in TWIST
			MOV BH, COLORSTORE[0]
			ADD BH, 08H
			MOV CX, 0B3BH
			MOV DX, 0E41H
			CALL CLEAR
		
			; Displays 'WORD TWIST'
			MOV DX, 0300H
			CALL CURSOR
			LEA DX, WORD_LOADING
			CALL DISPLAY
			
			POPA
		
		    ; Displays Loading Prompt 
			MOV DX, 1200H
			CALL CURSOR
			LEA DX, LOADING[BX]
			CALL DISPLAY			
			
			MOV DX, 1300H
			CALL CURSOR
			LEA DX, LOADING_BORDER
			CALL DISPLAY

			PUSHA
			MOV BH, 70H
			MOV CX, 1412H
			MOV DH, 14H
			MOV DL, LOOPSTORE[0]
			CALL CLEAR
			POPA
			
			INC COLORSTORE[0]
			INC LOOPSTORE[0]
			ADD BX, 51H
			
			CMP COLORSTORE[0], 07H
			IF E MOV COLORSTORE[0], 01H
			
			CMP BX, 243
			IF E MOV BX, 00H
			
			PUSHA
			MOV CX, 03H
			MOV DX, 00H
			CALL DELAY
			POPA
			
			DEC CX
			
			CMP CX, 00H
			IF E JMP LOAD2_DONE
	
	    JMP LOADREPEAT2
		
		LOAD2_DONE :

		RET
	GAME2_LOADINGSCREEN ENDP
	
	GAME2_INSTRUCTION PROC NEAR
	
		MOV AL, 00H
		CALL VIDEO_MODE
		
		MOV AH, 0CH
		INT 21h 
		
		; Coloring 'GAME INFORMATION'
		MOV BH, 02H
		MOV CX, 030CH
		MOV DX, 031BH
		CALL CLEAR
		
		; Coloring BORDERS
		MOV BH, 0EH
		MOV CX, 0401H
		MOV DX, 1526H
		CALL CLEAR
		
		; Coloring ARROWS
		MOV BH, 04H
		MOV CX, 0603H
		MOV DX, 1103H
		CALL CLEAR
		
		; Coloring TEXT
		MOV BH, 0FH
		MOV CX, 0605H
		MOV DX, 1124H
		CALL CLEAR
		
		; Coloring 'CONTINUE'
		MOV BH, 06H
		MOV CX, 1407H
		MOV DX, 141FH
		CALL CLEAR
		
		MOV DX, 0300H
		CALL CURSOR
		
		LEA DX, GAME2_INFO
		CALL DISPLAY
		
		; Hides CURSOR
		MOV BH, 00H
		MOV CX, 1600H
		MOV DX, 1601H
		CALL CLEAR
		
		MOV AH, 00H
		INT 16H
		
		RET
	GAME2_INSTRUCTION ENDP
	
	RESTORE_STRINGSTORE PROC NEAR
	
		MOV CX, 10H
		MOV BX, 00H
		
		RESTORESTRING :
		
			MOV STRINGSTORE[BX], ' '
			INC BX
		
		LOOP RESTORESTRING
		
		RET
	RESTORE_STRINGSTORE ENDP
	
	GAME2_SHUFFLER PROC NEAR
	
		INC SHUFFLE_STORE[0]
		
		PUSHA
		
		MOV DX, 1500H
		CALL CURSOR
	
		CMP LEVELSTORE[0], 01H
		IF NE JMP SHUFFLE2
		
				CMP SHUFFLE_STORE[0], 05H
				IF NE JMP SHUFFLE1A
				LEA DX, G2_LEVEL1_SHUFF1
				CALL DISPLAY
				MOV SHUFFLE_STORE[0], 00H
				POPA
				JMP LEVEL1_ASK
					
				SHUFFLE1A :
				CMP SHUFFLE_STORE[0], 01H
				IF NE JMP SHUFFLE1B
				LEA DX, G2_LEVEL1_SHUFF2
				CALL DISPLAY
				POPA
				JMP LEVEL1_ASK
					
				SHUFFLE1B :
				CMP SHUFFLE_STORE[0], 02H
				IF NE JMP SHUFFLE1C
				LEA DX, G2_LEVEL1_SHUFF3
				CALL DISPLAY
				POPA
				JMP LEVEL1_ASK

				SHUFFLE1C :
				CMP SHUFFLE_STORE[0], 03H
				IF NE JMP SHUFFLE1D
				LEA DX, G2_LEVEL1_SHUFF4
				CALL DISPLAY
				POPA
				JMP LEVEL1_ASK
				
				SHUFFLE1D :
				LEA DX, G2_LEVEL1_SHUFF5
				CALL DISPLAY
				POPA
				JMP LEVEL1_ASK
		
		SHUFFLE2 :
		CMP LEVELSTORE[0], 02H
		IF NE JMP SHUFFLE3
		
				CMP SHUFFLE_STORE[0], 05H
				IF NE JMP SHUFFLE2A
				LEA DX, G2_LEVEL2_SHUFF1
				CALL DISPLAY
				MOV SHUFFLE_STORE[0], 00H
				POPA
				JMP LEVEL2_ASK
					
				SHUFFLE2A :
				CMP SHUFFLE_STORE[0], 01H
				IF NE JMP SHUFFLE2B
				LEA DX, G2_LEVEL2_SHUFF2
				CALL DISPLAY
				POPA
				JMP LEVEL2_ASK
					
				SHUFFLE2B :
				CMP SHUFFLE_STORE[0], 02H
				IF NE JMP SHUFFLE2C
				LEA DX, G2_LEVEL2_SHUFF3
				CALL DISPLAY
				POPA
				JMP LEVEL2_ASK

				SHUFFLE2C :
				CMP SHUFFLE_STORE[0], 03H
				IF NE JMP SHUFFLE2D
				LEA DX, G2_LEVEL2_SHUFF4
				CALL DISPLAY
				POPA
				JMP LEVEL2_ASK
				
				SHUFFLE2D :
				LEA DX, G2_LEVEL2_SHUFF5
				CALL DISPLAY
				POPA
				JMP LEVEL2_ASK
		
		SHUFFLE3 :
		CMP LEVELSTORE[0], 03H
		IF NE JMP SHUFFLE4
				
				CMP SHUFFLE_STORE[0], 05H
				IF NE JMP SHUFFLE3A
				LEA DX, G2_LEVEL3_SHUFF1
				CALL DISPLAY
				MOV SHUFFLE_STORE[0], 00H
				POPA
				JMP LEVEL3_ASK
					
				SHUFFLE3A :
				CMP SHUFFLE_STORE[0], 01H
				IF NE JMP SHUFFLE3B
				LEA DX, G2_LEVEL3_SHUFF2
				CALL DISPLAY
				POPA
				JMP LEVEL3_ASK
					
				SHUFFLE3B :
				CMP SHUFFLE_STORE[0], 02H
				IF NE JMP SHUFFLE3C
				LEA DX, G2_LEVEL3_SHUFF3
				CALL DISPLAY
				POPA
				JMP LEVEL3_ASK

				SHUFFLE3C :
				CMP SHUFFLE_STORE[0], 03H
				IF NE JMP SHUFFLE3D
				LEA DX, G2_LEVEL3_SHUFF4
				CALL DISPLAY
				POPA
				JMP LEVEL3_ASK
				
				SHUFFLE3D :
				LEA DX, G2_LEVEL3_SHUFF5
				CALL DISPLAY
				POPA
				JMP LEVEL3_ASK
		
		
		SHUFFLE4 :
		CMP LEVELSTORE[0], 04H
		
		
				CMP SHUFFLE_STORE[0], 05H
				IF NE JMP SHUFFLE4A
				LEA DX, G2_LEVEL4_SHUFF1
				CALL DISPLAY
				MOV SHUFFLE_STORE[0], 00H
				POPA
				JMP LEVEL4_ASK
					
				SHUFFLE4A :
				CMP SHUFFLE_STORE[0], 01H
				IF NE JMP SHUFFLE4B
				LEA DX, G2_LEVEL4_SHUFF2
				CALL DISPLAY
				POPA
				JMP LEVEL4_ASK
					
				SHUFFLE4B :
				CMP SHUFFLE_STORE[0], 02H
				IF NE JMP SHUFFLE4C
				LEA DX, G2_LEVEL4_SHUFF3
				CALL DISPLAY
				POPA
				JMP LEVEL4_ASK

				SHUFFLE4C :
				CMP SHUFFLE_STORE[0], 03H
				IF NE JMP SHUFFLE4D
				LEA DX, G2_LEVEL4_SHUFF4
				CALL DISPLAY
				POPA
				JMP LEVEL4_ASK
				
				SHUFFLE4D :
				LEA DX, G2_LEVEL4_SHUFF5
				CALL DISPLAY
				POPA
				JMP LEVEL4_ASK
	
		RET
	GAME2_SHUFFLER ENDP
	
	GAME2_NEXTSTATE PROC NEAR
	
		; Coloring ARROWNEXT
		MOV BH, 04H
		MOV CX, 1648H
		MOV DX, 174FH
		CALL CLEAR
		
		MOV CX, 02H
		MOV DH, 16H
		MOV BX, 00H
		ARROWNEXTPRINT :
		
			MOV DL, 48H
			CALL CURSOR
			
			PUSH DX
			LEA DX, ARROWNEXT[BX]
			CALL DISPLAY
			POP DX
			
			INC DH
			ADD BX, 09H
		
		LOOP ARROWNEXTPRINT
		
		NEXTLEVEL :
		
			MOV AH, 07H
			INT 21H
			CMP AL, 0DH
			IF E JMP NEXTSTATE
			JMP NEXTLEVEL
			
			NEXTSTATE :
		
			CMP LEVELSTORE[0], 01H
			IF E JMP GAME2_LEVEL2
			
			CMP LEVELSTORE[0], 02H
			IF E JMP GAME2_LEVEL3
			
			CMP LEVELSTORE[0], 03H
			IF E JMP GAME2_LEVEL4
			
			CMP LEVELSTORE[0], 04H
			IF E JMP GAME2_CONGRATS
			
		RET
	GAME2_NEXTSTATE ENDP
	
	GAME2_LEVEL1 PROC NEAR
	
		MOV AL, 03H
		CALL VIDEO_MODE
		CALL CLEAR_ALL
		
		MOV SCORESTORE[0], 00H
		MOV LEVELSTORE[0], 01H
		MOV SHUFFLE_STORE[0], 00H
	
		MOV STATE1_STORE[0], 00H
		MOV STATE2_STORE[0], 00H
		MOV STATE3_STORE[0], 00H
		MOV STATE4_STORE[0], 00H
		MOV STATE5_STORE[0], 00H
		MOV STATE6_STORE[0], 00H
		MOV STATE7_STORE[0], 00H
		MOV STATE8_STORE[0], 00H
		MOV STATE9_STORE[0], 00H
		MOV STATE10_STORE[0], 00H
		
		; Coloring LEVEL 1
		MOV BH, 06H
		MOV CX, 012DH
		MOV DX, 013CH
		CALL CLEAR
		
		; Coloring INPUTBOX
		MOV BH, 0EH
		MOV CX, 0E1DH
		MOV DX, 104DH
		CALL CLEAR
		
		; Coloring CROSSWORD BOX
		MOV BH, 09H
		MOV CX, 0101H
		MOV DX, 151AH
		CALL CLEAR
		
		MOV DX, 0100H
		CALL CURSOR
		LEA DX, G2_LEVEL1
		CALL DISPLAY
	
		; Coloring SHUFFLED WORD
		MOV BH, 02H
		MOV CX, 1500H
		MOV DX, 174FH
		CALL CLEAR
		
		MOV DX, 1500H
		CALL CURSOR
		LEA DX, G2_LEVEL1_SHUFF1
		CALL DISPLAY
		
		; Coloring HINTS
		MOV BH, 08H
		MOV CX, 0320H
		MOV DX, 0C4CH
		CALL CLEAR
		
		MOV BX, 00H
		MOV LOOPSTORE[0], 03H
		MOV CX, 0AH
	
		REPRINT_TEXT :

			PUSHA
			MOV DH, LOOPSTORE[0]
			MOV DL, 20H
			CALL CURSOR
			POPA
		
			LEA DX, G2_LEVEL1_TEXT1[BX]
			CALL DISPLAY
			
			INC LOOPSTORE[0]
			ADD BX, 2FH
			
		LOOP REPRINT_TEXT 
		
		G2_LEVEL1_ASKMASTER :
		
		MOV CX, 0CH
		MOV DX, 1FH
		MOV BX, 00H
		
		LEVEL1_ASK :
		
		    MOV DH, 0FH
			CALL CURSOR
		
			G2_LEVEL1_ASKFALSE :
			
		
			MOV AH, 07H
			INT 21H
			
			CMP AL, 'c'
			IF E JMP G2_LEVEL1_ASKTRUE
			
			CMP AL, 'h'
			IF E JMP G2_LEVEL1_ASKTRUE
			
			CMP AL, 'r'
			IF E JMP G2_LEVEL1_ASKTRUE
			
			CMP AL, 'o'
			IF E JMP G2_LEVEL1_ASKTRUE
			
			CMP AL, 'n'
			IF E JMP G2_LEVEL1_ASKTRUE
			
			CMP AL, 's'
			IF E JMP G2_LEVEL1_ASKTRUE
			
			CMP AL, 'p'
			IF E JMP G2_LEVEL1_ASKTRUE
			
			CMP AL, 'e'
			IF E JMP G2_LEVEL1_ASKTRUE
			
			CMP AL, '0'
			IF E CALL GAME2_SHUFFLER
			
			CMP AL, 0DH
			IF NE JMP G2_LEVEL1_ASKFALSE
			IF E JMP G2_LEVEL1_COMPARE
			
			G2_LEVEL1_ASKTRUE :
			
				XOR AL, 00100000B
				PUSH DX
				MOV DL, AL
				CALL CHAR_DISPLAY
			    POP DX
				
				ADD DX, 04H
				MOV STRINGSTORE[BX], AL
				INC BX
				
		LOOP LEVEL1_ASK
		
		G2_LEVEL1_COMPARE :
		
		PUSHA
	    MOV DX, 0F1DH
		CALL CURSOR
	    LEA DX, G2_LEVEL1[1601]
		CALL DISPLAY
	    POPA
	
		CLD
		
		CMP BX, 08H
		IF NE JMP G2L1N2
		MOV CX, 08H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL1_ANS1
		REPE CMPSB
		IF E CALL GAME2_LEVEL1_STATE1
		
		G2L1N2 :
		CMP BX, 07H
		IF NE JMP G2L1N3
		MOV CX, 07H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL1_ANS2
		REPE CMPSB
		IF E CALL GAME2_LEVEL1_STATE2
		
		G2L1N3 :
		CMP BX, 07H
		IF NE JMP G2L1N4
		MOV CX, 07H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL1_ANS3
		REPE CMPSB
		IF E CALL GAME2_LEVEL1_STATE3
		
		G2L1N4 :
		CMP BX, 06H
		IF NE JMP G2L1N5
		MOV CX, 06H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL1_ANS4
		REPE CMPSB
		IF E CALL GAME2_LEVEL1_STATE4
		
		G2L1N5 :
		CMP BX, 06H
		IF NE JMP G2L1N6
		MOV CX, 06H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL1_ANS5
		REPE CMPSB
		IF E CALL GAME2_LEVEL1_STATE5
		
		G2L1N6 :
		CMP BX, 06H
		IF NE JMP G2L1N7
		MOV CX, 06H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL1_ANS6
		REPE CMPSB
		IF E CALL GAME2_LEVEL1_STATE6
		
		G2L1N7 :
		CMP BX, 05H
		IF NE JMP G2L1N8
		MOV CX, 05H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL1_ANS7
		REPE CMPSB
		IF E CALL GAME2_LEVEL1_STATE7
		
		G2L1N8 :
		CMP BX, 05H
		IF NE JMP G2L1N9
		MOV CX, 05H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL1_ANS8
		REPE CMPSB
		IF E CALL GAME2_LEVEL1_STATE8
		
		G2L1N9 :
		CMP BX, 05H
		IF NE JMP G2L1N10
		MOV CX, 05H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL1_ANS9
		REPE CMPSB
		IF E CALL GAME2_LEVEL1_STATE9
		
		G2L1N10 :
		CMP BX, 0CH
		IF NE JMP G2L1N1
		MOV CX, 0CH
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL1_ANS10
		REPE CMPSB
		IF E CALL GAME2_LEVEL1_STATE10
		
		G2L1N1 :
	    CMP SCORESTORE[0], 0AH
		IF NE JMP G2_LEVEL1_ASKMASTER
		IF E RET
		
		RET
	GAME2_LEVEL1 ENDP
	
	GAME2_LEVEL1_STATE1 PROC NEAR
					
		CMP STATE1_STORE[0], 01H
		IF E JMP G2_LEVEL1_ASKMASTER
				
		INC SCORESTORE[0]
		MOV STATE1_STORE[0], 01H
		
		CALL RESTORE_STRINGSTORE
		
		MOV RAND_STORE[0], 00H
		MOV CX, 08H
		MOV DL, 13H
		MOV DH, 05H
		
		G2L1STATE1 :
		
			CALL CURSOR
			
			PUSHA
			MOV BL, RAND_STORE[0]
			MOV AL, G2_LEVEL1_ANS1[BX]
			MOV BL, 0BH
			CALL CHAR_DISPLAY_ATTRIB
			POPA
				
			ADD DH, 02H
			INC RAND_STORE[0]
			
		LOOP G2L1STATE1
		
		; Coloring HINT1
		MOV BH, 0BH
		MOV CX, 0320H
		MOV DX, 0345H
		CALL CLEAR
		
		; Printing HINT1
		MOV DX, 0320H
		CALL CURSOR
		LEA DX, G2_LEVEL1_TEXT1
		CALL DISPLAY
		
		CMP SCORESTORE[0], 0AH
		IF NE JMP G2_LEVEL1_ASKMASTER
		IF E CALL GAME2_NEXTSTATE
		
		RET
	GAME2_LEVEL1_STATE1 ENDP 
	
