	GAME2_LEVEL2 PROC NEAR
	
		MOV SCORESTORE[0], 00H
		MOV LEVELSTORE[0], 02H
		MOV SHUFFLE_STORE[0], 00H
		
		MOV STATE1_STORE[0], 00H
		MOV STATE2_STORE[0], 00H
		MOV STATE3_STORE[0], 00H
		MOV STATE4_STORE[0], 00H
		MOV STATE5_STORE[0], 00H
		MOV STATE6_STORE[0], 00H
		MOV STATE7_STORE[0], 00H
		MOV STATE8_STORE[0], 00H
		MOV STATE9_STORE[0], 00H
		MOV STATE10_STORE[0], 00H
		
		; Coloring LEVEL 2
		MOV BH, 06H
		MOV CX, 012DH
		MOV DX, 013CH
		CALL CLEAR
		
		; Coloring INPUTBOX
		MOV BH, 0EH
		MOV CX, 0E1DH
		MOV DX, 104DH
		CALL CLEAR
		
		; Coloring CROSSWORD BOX
		MOV BH, 09H
		MOV CX, 0101H
		MOV DX, 151AH
		CALL CLEAR
		
		MOV DX, 0100H
		CALL CURSOR
		LEA DX, G2_LEVEL2
		CALL DISPLAY
	
		; Coloring SHUFFLED WORD
		MOV BH, 02H
		MOV CX, 1500H
		MOV DX, 174FH
		CALL CLEAR
		
		MOV DX, 1500H
		CALL CURSOR
		LEA DX, G2_LEVEL2_SHUFF1
		CALL DISPLAY
		
		; Coloring HINTS
		MOV BH, 08H
		MOV CX, 0320H
		MOV DX, 0C4DH
		CALL CLEAR
		
		MOV BX, 00H
		MOV LOOPSTORE[0], 03H
		MOV CX, 0AH
	
		REPRINT_TEXT2 :

			PUSHA
			MOV DH, LOOPSTORE[0]
			MOV DL, 20H
			CALL CURSOR
			POPA
		
			LEA DX, G2_LEVEL2_TEXT1[BX]
			CALL DISPLAY
			
			INC LOOPSTORE[0]
			ADD BX, 2FH
			
		LOOP REPRINT_TEXT2
		
		G2_LEVEL2_ASKMASTER :
		
		MOV CX, 0AH
		MOV DL, 24H
		MOV BX, 00H
		
		LEVEL2_ASK :
		
		    MOV DH, 0FH
			CALL CURSOR
		
			G2_LEVEL2_ASKFALSE :
			
		
			MOV AH, 07H
			INT 21H
			
			CMP AL, 'a'
			IF E JMP G2_LEVEL2_ASKTRUE
			
			CMP AL, 'r'
			IF E JMP G2_LEVEL2_ASKTRUE
			
			CMP AL, 'm'
			IF E JMP G2_LEVEL2_ASKTRUE
	
			CMP AL, 'g'
			IF E JMP G2_LEVEL2_ASKTRUE
			
			CMP AL, 'e'
			IF E JMP G2_LEVEL2_ASKTRUE
			
			CMP AL, 'd'
			IF E JMP G2_LEVEL2_ASKTRUE
			
			CMP AL, 'o'
			IF E JMP G2_LEVEL2_ASKTRUE
			
			CMP AL, 'n'
			IF E JMP G2_LEVEL2_ASKTRUE
			
			CMP AL, '0'
			IF E CALL GAME2_SHUFFLER
			
			CMP AL, 0DH
			IF NE JMP G2_LEVEL2_ASKFALSE
			IF E JMP G2_LEVEL2_COMPARE
			
			G2_LEVEL2_ASKTRUE :
			
				XOR AL, 00100000B
				PUSH DX
				MOV DL, AL
				CALL CHAR_DISPLAY
			    POP DX
				
				ADD DX, 04H
				MOV STRINGSTORE[BX], AL
				INC BX
				
		LOOP LEVEL2_ASK
		
		G2_LEVEL2_COMPARE :
		
		PUSHA
	    MOV DX, 0F22H
		CALL CURSOR
	    LEA DX, G2_LEVEL2[1601]
		CALL DISPLAY
	    POPA
	
		CLD
		
		CMP BX, 09H
		IF NE JMP G2L2N2
		MOV CX, 09H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL2_ANS1
		REPE CMPSB
		IF E CALL GAME2_LEVEL2_STATE1
		
		G2L2N2 :
		CMP BX, 07H
		IF NE JMP G2L2N3
		MOV CX, 07H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL2_ANS2
		REPE CMPSB
		IF E CALL GAME2_LEVEL2_STATE2
		
		G2L2N3 :
		CMP BX, 07H
		IF NE JMP G2L2N4
		MOV CX, 07H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL2_ANS3
		REPE CMPSB
		IF E CALL GAME2_LEVEL2_STATE3
		
		G2L2N4 :
		CMP BX, 06H
		IF NE JMP G2L2N5
		MOV CX, 06H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL2_ANS4
		REPE CMPSB
		IF E CALL GAME2_LEVEL2_STATE4
		
		G2L2N5 :
		CMP BX, 06H
		IF NE JMP G2L2N6
		MOV CX, 06H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL2_ANS5
		REPE CMPSB
		IF E CALL GAME2_LEVEL2_STATE5
		
		G2L2N6 :
		CMP BX, 06H
		IF NE JMP G2L2N7
		MOV CX, 06H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL2_ANS6
		REPE CMPSB
		IF E CALL GAME2_LEVEL2_STATE6
		
		G2L2N7 :
		CMP BX, 05H
		IF NE JMP G2L2N8
		MOV CX, 05H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL2_ANS7
		REPE CMPSB
		IF E CALL GAME2_LEVEL2_STATE7
		
		G2L2N8 :
		CMP BX, 05H
		IF NE JMP G2L2N9
		MOV CX, 05H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL2_ANS8
		REPE CMPSB
		IF E CALL GAME2_LEVEL2_STATE8
		
		G2L2N9 :
		CMP BX, 05H
		IF NE JMP G2L2N10
		MOV CX, 05H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL2_ANS9
		REPE CMPSB
		IF E CALL GAME2_LEVEL2_STATE9
		
		G2L2N10 :
		CMP BX, 0AH
		IF NE JMP G2L2N1
		MOV CX, 0AH
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL2_ANS10
		REPE CMPSB
		IF E CALL GAME2_LEVEL2_STATE10
		
		G2L2N1 :
	    CMP SCORESTORE[0], 0AH
		IF NE JMP G2_LEVEL2_ASKMASTER
		IF E RET
		
		RET
	GAME2_LEVEL2 ENDP
	
