		CMP BX, 06H
		IF NE JMP G2L4N6
		MOV CX, 06H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL4_ANS5
		REPE CMPSB
		IF E CALL GAME2_LEVEL4_STATE5
		
		G2L4N6 :
		CMP BX, 05H
		IF NE JMP G2L4N7
		MOV CX, 05H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL4_ANS6
		REPE CMPSB
		IF E CALL GAME2_LEVEL4_STATE6
		
		G2L4N7 :
		CMP BX, 05H
		IF NE JMP G2L4N8
		MOV CX, 05H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL4_ANS7
		REPE CMPSB
		IF E CALL GAME2_LEVEL4_STATE7
		
		G2L4N8 :
		CMP BX, 05H
		IF NE JMP G2L4N9
		MOV CX, 05H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL4_ANS8
		REPE CMPSB
		IF E CALL GAME2_LEVEL4_STATE8
		
		G2L4N9 :
		CMP BX, 05H
		IF NE JMP G2L4N10
		MOV CX, 05H
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL4_ANS9
		REPE CMPSB
		IF E CALL GAME2_LEVEL4_STATE9
		
		G2L4N10 :
		CMP BX, 0BH
		IF NE JMP G2L4N1
		MOV CX, 0BH
		LEA DI, STRINGSTORE
		LEA SI, G2_LEVEL4_ANS10
		REPE CMPSB
		IF E CALL GAME2_LEVEL4_STATE10
		
		G2L4N1:
	    CMP SCORESTORE[0], 0AH
		IF NE JMP G2_LEVEL4_ASKMASTER
		IF E RET
		
		RET
	GAME2_LEVEL4 ENDP
	
	GAME2_LEVEL4_STATE1 PROC NEAR
	
		CMP STATE1_STORE[0], 01H
		IF E JMP G2_LEVEL4_ASKMASTER
		
		INC SCORESTORE[0]
		MOV STATE1_STORE[0], 01H
		
		CALL RESTORE_STRINGSTORE
		
		MOV RAND_STORE[0], 00H
		MOV CX, 08H
		MOV DL, 02H
		MOV DH, 03H
		
		G2L4STATE1 :
		
			CALL CURSOR
			
			PUSHA
			MOV BL, RAND_STORE[0]
			MOV AL, G2_LEVEL4_ANS1[BX]
			MOV BL, 0BH
			CALL CHAR_DISPLAY_ATTRIB
			POPA
				
			ADD DL, 02H
			INC RAND_STORE[0]
			
		LOOP G2L4STATE1
		
		; Coloring HINT1
		MOV BH, 0BH
		MOV CX, 0320H
		MOV DX, 0345H
		CALL CLEAR
		
		; Printing HINT1
		MOV DX, 0320H
		CALL CURSOR
		LEA DX, G2_LEVEL4_TEXT1
		CALL DISPLAY
		
		CMP SCORESTORE[0], 0AH
		IF NE JMP G2_LEVEL4_ASKMASTER
		IF E CALL GAME2_NEXTSTATE
		
		RET
	GAME2_LEVEL4_STATE1 ENDP
	
