	EXITPAGE PROC NEAR
	
		CALL CLEAR_ALL
		
		MOV DX, 0700H
		CALL CURSOR
		LEA DX, EXITMESSAGE
		CALL DISPLAY
		
		MOV DX, 184FH
		CALL CURSOR
		
		INT 20H
		
		RET
	EXITPAGE ENDP
	
	GAME2_CONGRATS PROC NEAR      
		
		CALL CLEAR_ALL
	                         
		; Printing Congrats!
		MOV DX, 0300H
		CALL CURSOR
		LEA DX, GAME2_ENDCRED_TOP
		CALL DISPLAY
		
		MOV DX, 0400H
		CALL CURSOR
		LEA DX, GAME2_ENDCRED_TOP[43]
		CALL DISPLAY
		
		; Coloring Border
		MOV BH, 05H
		MOV CX, 0C01H
		MOV DX, 1835H
		CALL CLEAR
		
		; Coloring MENU TABLE Border
		MOV BH, 03H
		MOV CX, 0B3AH
		MOV DX, 184AH
		CALL CLEAR
		
		; Coloring MENU TABLE Menu 
		MOV BH, 02H
		MOV CX, 0C3BH
		MOV DX, 0C49H
		CALL CLEAR
		
		; Coloring MENU TABLE Level
		MOV BH, 06H
		MOV CX, 0D3BH
		MOV DX, 1649H
		CALL CLEAR
		
		; Coloring MENU TABLE Exit
		MOV BH, 04H
		MOV CX, 173BH
		MOV DX, 1749H
		CALL CLEAR
		
		MOV BH, 0EH
		MOV CX, 0D03H
		MOV DX, 1733H
		CALL CLEAR
		        
		MOV DX, 0A01H
		CALL CURSOR
	
		LEA DX, GAME2_ENDCRED_BORD
		CALL DISPLAY
		
		MOV DH, 0AH
		MOV DL, 3AH
		MOV CX, 0EH
		MOV BX, 00H
		
		REPRINT_TABLE :
			
			CALL CURSOR
		
			PUSH DX
			LEA DX, CRED2_TABLE[BX]
			CALL DISPLAY
			POP DX
			
			ADD BX, 12H
			INC DH
		
		LOOP REPRINT_TABLE
		
		MOV DX, 1800H
		CALL CURSOR
		LEA DX, SCROLLPROMPT
		CALL DISPLAY
		
		MOV CX, 36H
		MOV BX, 00H
		
		UP_CREDS2_AGAIN :
		
			CRED2_ASK :
			MOV AH, 07H
			INT 21H
			
			CMP AL, 'm'
			IF E JMP MASTER_JUMP
			CMP AL, '1'
			IF E CALL GAME2_LEVEL1
			CMP AL,	'2'
			IF E CALL GAME2_LEVEL2
			CMP AL, '3'
			IF E CALL GAME2_LEVEL3
			CMP AL,	'4'
			IF E CALL GAME2_LEVEL4
			CMP AL, 'x'
			IF E CALL EXITPAGE
			CMP AL, 'w'
			IF NE JMP CRED2_ASK
	
			PUSHA
			MOV AX, 0601H       
			MOV BH, 0EH
			MOV CX, 0C03H
			MOV DX, 1633H
			INT 10H
		
			MOV DX, 1603H
			CALL CURSOR
			POPA
			
			LEA DX, GAME2_ENDCREDS2[BX]
			CALL DISPLAY
			
	
			ADD BX, 32H
			DEC CX
			
			MOV AH, 0CH
			INT 21H
			
		CMP CX, 00H
		IF NE JMP UP_CREDS2_AGAIN
	
		CRED2_REASK :
			MOV AH, 07H
			INT 21H
			
			CMP AL, 'm'
			IF E JMP MASTER_JUMP
			CMP AL, '1'
			IF E CALL GAME2_LEVEL1
			CMP AL,	'2'
			IF E CALL GAME2_LEVEL2
			CMP AL, '3'
			IF E CALL GAME2_LEVEL3
			CMP AL,	'4'
			IF E CALL GAME2_LEVEL4
			CMP AL, 'x'
			IF E CALL EXITPAGE
			CMP AL, 'w'
			IF NE JMP CRED2_REASK
		
		RET
	GAME2_CONGRATS ENDP
		
	
	